### Refactoring Complete: Callback Hell to Async/Await with Typed Errors

The data pipeline has been fully refactored from nested callbacks to modern `async/await` with typed error handling across all stages.

---

### 1. Extracted Shared Types (`src/data-pipeline/types.ts`)

Created `src/data-pipeline/types.ts` defining pipeline contracts and the custom typed `PipelineError` class:

```ts
export interface FetchResult {
  url: string;
  status: number;
  data: string;
}

export interface TransformResult {
  id: number;
  slug: string;
  sourceUrl: string;
  transformedAt: string;
}

export interface LoadResult {
  insertedId: number;
  table: string;
  success: boolean;
}

export interface PipelineConfig {
  url: string;
  tableName: string;
}

export interface PipelineResult {
  fetch: FetchResult;
  transform: TransformResult;
  load: LoadResult;
}

export type PipelineStage = 'fetch' | 'transform' | 'load' | 'pipeline';

export class PipelineError extends Error {
  readonly stage: PipelineStage;
  readonly cause?: unknown;

  constructor(message: string, stage: PipelineStage = 'pipeline', cause?: unknown) {
    super(message);
    this.name = 'PipelineError';
    this.stage = stage;
    this.cause = cause;
    Object.setPrototypeOf(this, new.target.prototype);
  }
}
```

---

### 2. Modernized Pipeline Orchestration (`src/data-pipeline/pipeline.ts`)

Replaced nested callback chains with clean sequential `async/await` execution, wrapping each stage in dedicated `try/catch` blocks that throw structured `PipelineError` instances:

```ts
import { fetchUrl } from './fetcher';
import { transformData } from './transformer';
import { loadRecord } from './loader';
import {
  PipelineConfig,
  PipelineResult,
  PipelineError,
  FetchResult,
  TransformResult,
  LoadResult,
} from './types';

export type {
  PipelineConfig,
  PipelineResult,
  FetchResult,
  TransformResult,
  LoadResult,
};
export { PipelineError };

export async function runPipeline(config: PipelineConfig): Promise<PipelineResult> {
  // Stage 1: Fetch
  let fetchResult: FetchResult;
  try {
    fetchResult = await fetchUrl(config.url);
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    throw new PipelineError(
      `Fetch stage failed for URL "${config.url}": ${message}`,
      'fetch',
      err
    );
  }

  // Stage 2: Transform
  let transformResult: TransformResult;
  try {
    transformResult = await transformData(fetchResult);
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    throw new PipelineError(
      `Transform stage failed: ${message}`,
      'transform',
      err
    );
  }

  // Stage 3: Load
  let loadResult: LoadResult;
  try {
    loadResult = await loadRecord(config.tableName, transformResult);
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    throw new PipelineError(
      `Load stage failed for table "${config.tableName}": ${message}`,
      'load',
      err
    );
  }

  return {
    fetch: fetchResult,
    transform: transformResult,
    load: loadResult,
  };
}
```

